import { COPY_ONLY_CLASS, NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { useColorAssist } from "@hunt/puzzle-components";
import React from "react";

const TABLE_CELL_CLASS_PREFIX = "text-center px-4 ";
const BLUE = "text-[#003DA5]";
const GREEN = "text-[#00843D]";
const ORANGE = "text-[#ED8B00]";
const RED = "text-[#DA291C]";

type RowSpec = {
  text: string[];
  tailwindHex: string;
  colorName: string;
};

const toClassNamePrefix = (showColorName: boolean) =>
  showColorName ? "" : "hidden ";

export const NodeLines = () => {
  const [showColorName, setShowColorName] = useColorAssist();

  const DATA: (RowSpec | undefined)[] = [
    {
      text: ["1_5", "(5 ⬤)", "5_4", "(1 ⬤)", "9_2", "(2 ⬤)", "7_1"],
      tailwindHex: BLUE,
      colorName: "Blue",
    },
    {
      text: [
        "1_9",
        "(1 ⬤)",
        "2_15",
        "(5 ⬤)",
        "6_2",
        "(7 ⬤)",
        "3_8",
        "(3 ⬤)",
        "6_8",
        "(3 ⬤)",
        "5_3",
      ],
      tailwindHex: GREEN,
      colorName: "Green",
    },
    undefined,
    {
      text: [
        "2_4",
        "(6 ⬤)",
        "3_8",
        "(1 ⬤)",
        "7_2",
        "(2 ⬤)",
        "5_1",
        "(3 ⬤)",
        "5_1",
      ],
      tailwindHex: RED,
      colorName: "Red",
    },
    {
      text: [
        "5_2",
        "(4 ⬤)",
        "1_14",
        "(3 ⬤)",
        "9_6",
        "(2 ⬤)",
        "2_4",
        "(2 ⬤)",
        "1_13",
        "(3 ⬤)",
        "7_3",
      ],
      tailwindHex: ORANGE,
      colorName: "Orange",
    },
    {
      text: [
        "3_7",
        "(3 ⬤)",
        "_10",
        "(2 ⬤)",
        "7_8",
        "(6 ⬤)",
        "7_2",
        "(4 ⬤)",
        "1_6",
        "(4 ⬤)",
        "10_",
      ],
      tailwindHex: GREEN,
      colorName: "Green",
    },
    undefined,
    {
      text: [
        "3_3",
        "(2 ⬤)",
        "6_",
        "(1 ⬤)",
        "8_1",
        "(1 ⬤)",
        "6_2",
        "8_7",
        "8_",
        "(7 ⬤)",
        "3_4",
      ],
      tailwindHex: RED,
      colorName: "Red",
    },
    undefined,
    {
      text: ["5_2", "(2 ⬤)", "_12", "4_1", "(2 ⬤)", "2_4"],
      tailwindHex: RED,
      colorName: "Red",
    },
    {
      text: [
        "6_8",
        "(1 ⬤)",
        "5_2",
        "(2 ⬤)",
        "7_7",
        "(5 ⬤)",
        "2_8",
        "(7 ⬤)",
        "3_11",
      ],
      tailwindHex: GREEN,
      colorName: "Green",
    },
    {
      text: [
        "5_10",
        "(6 ⬤)",
        "2_12",
        "(5 ⬤)",
        "2_10",
        "(4 ⬤)",
        "4_9",
        "(3 ⬤)",
        "10_2",
      ],
      tailwindHex: GREEN,
      colorName: "Green",
    },
  ];

  return (
    <div className="flex flex-col justify-center items-center">
      <table className="table-auto">
        <tr>
          <td className={TABLE_CELL_CLASS_PREFIX}></td>
          <td className={TABLE_CELL_CLASS_PREFIX}>↓</td>
          <td className={TABLE_CELL_CLASS_PREFIX}></td>
          <td className={TABLE_CELL_CLASS_PREFIX}>↓</td>
        </tr>
        {DATA.map((values, idx) => {
          if (values === undefined) {
            return (
              <tr key={idx}>
                <td colSpan={4}>{"\u00A0"}</td>
              </tr>
            );
          } else {
            const { text, tailwindHex, colorName } = values;
            const classNames = TABLE_CELL_CLASS_PREFIX + tailwindHex;
            return (
              <tr key={idx}>
                <td className={TABLE_CELL_CLASS_PREFIX}>
                  <span
                    className={toClassNamePrefix(showColorName) + NO_COPY_CLASS}
                  >
                    {colorName}:
                  </span>
                  <span className={COPY_ONLY_CLASS}>{colorName}</span>
                </td>
                <td className={classNames}>{text[0]}</td>
                <td className={classNames}>
                  {text
                    .slice(1, text.length - 1)
                    .join("\u00A0\u00A0\u00A0\u00A0\u00A0")}
                </td>
                <td className={classNames}>{text[text.length - 1]}</td>
              </tr>
            );
          }
        })}
      </table>
      {/* Checkbox to toggle the color name display */}
      <div className={"mt-4 flex justify-start " + NO_COPY_CLASS}>
        <label className="flex items-center space-x-2 cursor-pointer">
          <input
            type="checkbox"
            checked={showColorName}
            onChange={() => {
              setShowColorName(!showColorName);
            }}
            className="h-4 w-4 rounded border-gray-300"
            aria-label="Show color names alongside colored text"
          />
          <span>Show color names</span>
        </label>
      </div>
    </div>
  );
};
